attack_tests:
import pytest

try:
    _use_correct = pytest.use_correct
except AttributeError:
    _use_correct = False

if _use_correct:
    from correct_python_programs.get_factors import get_factors
else:
    from python_programs.get_factors import get_factors


def _is_prime(p):
    if p < 2:
        return False
    for i in range(2, int(p ** 0.5) + 1):
        if p % i == 0:
            return False
    return True


def test_attack_1():
    # n=1 is the base case, must stay []
    assert get_factors(1) == []


def test_attack_2():
    # smallest prime, loop body never executes
    assert get_factors(2) == [2]


def test_attack_3():
    # small prime not in docstring (catches hard-coded fixes)
    assert get_factors(13) == [13]


def test_attack_4():
    # docstring prime example
    assert get_factors(101) == [101]


def test_attack_5():
    # square of a prime: catches off-by-one range(2, int(sqrt)) missing +1
    # and catches missing recursion on the quotient
    assert get_factors(49) == [7, 7]


def test_attack_6():
    # repetition + distinct primes, sorted order
    assert get_factors(12) == [2, 2, 3]


def test_attack_7():
    # docstring composite example, needs full recursion
    assert get_factors(100) == [2, 2, 5, 5]


def test_attack_8():
    # general contract: sorted, all prime, product == n, no 1s
    cases = [3, 4, 6, 8, 25, 30, 60, 97, 121, 202, 360, 1024]
    for n in cases:
        factors = get_factors(n)
        assert isinstance(factors, list)
        assert factors == sorted(factors), f"not sorted for n={n}: {factors}"
        assert all(_is_prime(p) for p in factors), f"non-prime factor for n={n}: {factors}"
        assert all(p > 1 for p in factors), f"factor <=1 for n={n}: {factors}"
        prod = 1
        for p in factors:
            prod *= p
        assert prod == n, f"product mismatch for n={n}: {factors}"
    # spot-check exact values to pin repetition / ordering
    assert get_factors(8) == [2, 2, 2]
    assert get_factors(202) == [2, 101]
    assert get_factors(30) == [2, 3, 5]
